import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final int MAXN = 2345678;
        Scanner sc = new Scanner(System.in);

        int total_nums = sc.nextInt();
        int max_k = sc.nextInt();

        double[] real_probs = new double[total_nums];
        double[] probs = new double[total_nums];
        int[] position_idx = new int[total_nums];
        double[] final_results = new double[total_nums];

        int count_valid = 0;
        for (int i = 0; i < total_nums; i++) {
            real_probs[i] = sc.nextDouble();
            if (real_probs[i] > 1e-4) {
                position_idx[count_valid] = i;
                probs[count_valid] = real_probs[i];
                count_valid++;
            }
        }

        max_k = Math.min(max_k, count_valid);

        int[] popcnt = new int[1 << count_valid];
        double[] dp_state = new double[1 << count_valid];

        // Precompute popcnt for all masks
        popcnt[0] = 0;
        for (int mask = 1; mask < (1 << count_valid); mask++) {
            popcnt[mask] = popcnt[mask & (mask - 1)] + 1;
        }

        // Initialize dp_state
        for (int mask = 0; mask < (1 << count_valid); mask++) {
            dp_state[mask] = 0.0;
        }

        // Initialize final_results
        for (int i = 0; i < total_nums; i++) {
            final_results[i] = 0.0;
        }

        dp_state[0] = 1.0;

        for (int mask = 0; mask < (1 << count_valid); mask++) {
            if (popcnt[mask] == max_k) {
                for (int j = 0; j < count_valid; j++) {
                    if ((mask & (1 << j)) != 0) {
                        final_results[position_idx[j]] += dp_state[mask];
                    }
                }
                continue;
            }
            double sum_probs = 0.0;
            for (int j = 0; j < count_valid; j++) {
                if ((mask & (1 << j)) != 0) continue;
                sum_probs += probs[j];
            }
            double ratio = sum_probs > 0 ? dp_state[mask] / sum_probs : 0;
            for (int j = 0; j < count_valid; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int next_mask = mask | (1 << j);
                dp_state[next_mask] += probs[j] * ratio;
            }
        }

        for (int i = 0; i < total_nums; i++) {
            if (i > 0) System.out.print(" ");
            System.out.printf("%.17f", final_results[i]);
        }
        System.out.println();
        sc.close();
    }
}
